var builder = WebApplication.CreateBuilder(args);
builder.Services.AddDbContext<TicketsDb>(o => o.UseSqlite("Data Source=bookings.db"));
var app = builder.Build();

using (var scope = app.Services.CreateScope())
    scope.ServiceProvider.GetRequiredService<TicketsDb>().Database.EnsureCreated();

app.MapPost("/bookings", async (BookingEdit edit, TicketsDb db, CancellationToken ct) =>
{
    var booking = new Booking { Note = edit.Note, Version = 1 };
    db.Bookings.Add(booking);
    await db.SaveChangesAsync(ct);
    return Results.Created($"/bookings/{booking.Id}", booking);
});

app.MapGet("/bookings/{id:int}", async (int id, TicketsDb db, CancellationToken ct) =>
    await db.Bookings.AsNoTracking().FirstOrDefaultAsync(b => b.Id == id, ct) is { } b ? Results.Ok(b) : Results.NotFound());

app.MapPut("/bookings/{id:int}", async (int id, BookingEdit edit, TicketsDb db, CancellationToken ct) =>
{
    var booking = await db.Bookings.FirstOrDefaultAsync(b => b.Id == id, ct);
    if (booking is null) return Results.NotFound();

    // Compare with the version the client loaded, not the one we just read.
    db.Entry(booking).Property(b => b.Version).OriginalValue = edit.Version;
    booking.Note = edit.Note;
    booking.Version = edit.Version + 1;
    try
    {
        await db.SaveChangesAsync(ct);
        return Results.Ok(booking);
    }
    catch (DbUpdateConcurrencyException)
    {
        return Results.Conflict(new { error = "The booking was changed by someone else. Reload it." });
    }
});

app.Run();

record BookingEdit(string Note, int Version);

class Booking
{
    public int Id { get; set; }
    public string Note { get; set; } = "";
    [ConcurrencyCheck] public int Version { get; set; }
}

class TicketsDb(DbContextOptions<TicketsDb> options) : DbContext(options)
{
    public DbSet<Booking> Bookings => Set<Booking>();
}
